const insertUserAvatarLocation = `-- name: InsertUserAvatarLocation :execrows
INSERT INTO identity.user_avatar_object_locations (
    object_id,
    backend_id,
    object_key,
    version_id,
    observed_byte_length,
    observed_sha256,
    verified_at
) VALUES (
    $1,
    $2,
    $3,
    $4,
    $5,
    $6,
    $7
)
ON CONFLICT (backend_id, object_key) DO UPDATE SET
    version_id = CASE
        WHEN identity.user_avatar_object_locations.object_id = EXCLUDED.object_id
          AND identity.user_avatar_object_locations.observed_byte_length = EXCLUDED.observed_byte_length
          AND identity.user_avatar_object_locations.observed_sha256 = EXCLUDED.observed_sha256
        THEN COALESCE(EXCLUDED.version_id, identity.user_avatar_object_locations.version_id)
        ELSE identity.user_avatar_object_locations.version_id
    END,
    verified_at = CASE
        WHEN identity.user_avatar_object_locations.object_id = EXCLUDED.object_id
          AND identity.user_avatar_object_locations.observed_byte_length = EXCLUDED.observed_byte_length
          AND identity.user_avatar_object_locations.observed_sha256 = EXCLUDED.observed_sha256
        THEN GREATEST(identity.user_avatar_object_locations.verified_at, EXCLUDED.verified_at)
        ELSE identity.user_avatar_object_locations.verified_at
    END
WHERE identity.user_avatar_object_locations.object_id = EXCLUDED.object_id
  AND identity.user_avatar_object_locations.observed_byte_length = EXCLUDED.observed_byte_length
  AND identity.user_avatar_object_locations.observed_sha256 = EXCLUDED.observed_sha256
`

type InsertUserAvatarLocationParams struct {
	ObjectID           uuid.UUID
	BackendID          string
	ObjectKey          string
	VersionID          pgtype.Text
	ObservedByteLength int64
	ObservedSha256     []byte
	VerifiedAt         pgtype.Timestamptz
}

func (q *Queries) InsertUserAvatarLocation(ctx context.Context, arg InsertUserAvatarLocationParams) (int64, error) {
	result, err := q.db.Exec(ctx, insertUserAvatarLocation,
		arg.ObjectID,
		arg.BackendID,
		arg.ObjectKey,
		arg.VersionID,
		arg.ObservedByteLength,
		arg.ObservedSha256,
		arg.VerifiedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

