const touchActiveWebSession = `-- name: TouchActiveWebSession :exec
UPDATE identity.sessions
SET last_seen_at = $1
WHERE token_hash = $2
  AND audience = 'web'
  AND revoked_at IS NULL
  AND expires_at > $1
  AND last_seen_at <= $1::timestamptz - interval '5 minutes'
`

type TouchActiveWebSessionParams struct {
	SeenAt    pgtype.Timestamptz
	TokenHash []byte
}

// Activity writes are coalesced to five-minute buckets. This keeps the user
// projection useful without turning every authenticated request into a row
// update or collecting a detailed browsing timeline.
func (q *Queries) TouchActiveWebSession(ctx context.Context, arg TouchActiveWebSessionParams) error {
	_, err := q.db.Exec(ctx, touchActiveWebSession, arg.SeenAt, arg.TokenHash)
	return err
}

