const upsertTrackerPasskeyProjection = `-- name: UpsertTrackerPasskeyProjection :one
INSERT INTO identity.tracker_passkey_hmac (
    user_id,
    credential_ref,
    lookup_hmac,
    vault_version,
    created_at,
    updated_at
)
SELECT
    users.id,
    users.credential_ref,
    $1::bytea,
    $2::bigint,
    $3::timestamptz,
    $3::timestamptz
FROM identity.users AS users
WHERE users.id = $4::uuid
  AND users.credential_ref = $5::uuid
  AND users.status = 'active'
ON CONFLICT (user_id) DO UPDATE SET
    lookup_hmac = CASE
        WHEN identity.tracker_passkey_hmac.vault_version < EXCLUDED.vault_version
        THEN EXCLUDED.lookup_hmac
        ELSE identity.tracker_passkey_hmac.lookup_hmac
    END,
    vault_version = GREATEST(
        identity.tracker_passkey_hmac.vault_version,
        EXCLUDED.vault_version
    ),
    updated_at = GREATEST(
        identity.tracker_passkey_hmac.updated_at,
        EXCLUDED.updated_at
    )
WHERE identity.tracker_passkey_hmac.credential_ref = EXCLUDED.credential_ref
  AND (
      identity.tracker_passkey_hmac.vault_version < EXCLUDED.vault_version
      OR (
          identity.tracker_passkey_hmac.vault_version = EXCLUDED.vault_version
          AND identity.tracker_passkey_hmac.lookup_hmac = EXCLUDED.lookup_hmac
      )
  )
RETURNING
    user_id,
    credential_ref,
    lookup_hmac,
    vault_version,
    created_at,
    updated_at
`

type UpsertTrackerPasskeyProjectionParams struct {
	LookupHmac    []byte
	VaultVersion  int64
	BoundAt       pgtype.Timestamptz
	UserID        uuid.UUID
	CredentialRef uuid.UUID
}

func (q *Queries) UpsertTrackerPasskeyProjection(ctx context.Context, arg UpsertTrackerPasskeyProjectionParams) (IdentityTrackerPasskeyHmac, error) {
	row := q.db.QueryRow(ctx, upsertTrackerPasskeyProjection,
		arg.LookupHmac,
		arg.VaultVersion,
		arg.BoundAt,
		arg.UserID,
		arg.CredentialRef,
	)
	var i IdentityTrackerPasskeyHmac
	err := row.Scan(
		&i.UserID,
		&i.CredentialRef,
		&i.LookupHmac,
		&i.VaultVersion,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
